#!/bin/bash
# DOFEK rant, v2: built ON the voice timeline.
# One continuous voice take (vo/voice.wav) is the master clock. Each talking
# shot was generated by wan2_7 from the slice of that take it has to speak, so
# frame 0 of a shot is the first sample of its slice. Segment lengths are given
# in FRAMES so the picture cannot drift against the continuous audio.
set -e
R=/tmp/claude-0/-home-user-SHOPIFY/06af39bb-792a-5cc6-a4be-ecbf44972499/scratchpad/rant
A=/tmp/claude-0/-home-user-SHOPIFY/06af39bb-792a-5cc6-a4be-ecbf44972499/scratchpad/anim/clips
cd $R; S=seg2; rm -rf $S; mkdir -p $S
V="scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,fps=24,setsar=1"
sg () { ffmpeg -y -loglevel error -ss $2 -i $1 -vf "$V" -frames:v $3 -an \
  -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/$4.mp4; }
#   source        in    frames  out        film time      audio slice starts
sg cl/WA.mp4      0     58      q01   #    0.00            0.00
sg cl/WB.mp4      0     115     q02   #    2.417           2.42
sg cl/WC.mp4      0     124     q03   #    7.208           7.21
sg $A/c10.mp4     0.35  54      q04   #   12.375  "ולחזור ללכת כמו בן אדם"
sg $A/c02.mp4     0.60  39      q05   #   14.625  "לא כמו חיה פצועה"
sg $A/c01.mp4     0.45  72      q06   #   16.250  "לא נמאס לך ללכת לעבודה ולסבול"
sg cl/WD.mp4      0     117     q07   #   19.250          19.26
sg cl/WE.mp4      0     118     q08   #   24.125          24.05  (+2 frames: this shot's mouth led by 0.08s)
sg cl/WF.mp4      0     70      q09   #   29.042          29.04
ffmpeg -y -loglevel error -framerate 24 -i t/endseq/f%04d.png -vf "fps=24,setsar=1" -frames:v 77 -an \
  -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/q10.mp4
cd $S; : > list.txt; for f in q01 q02 q03 q04 q05 q06 q07 q08 q09 q10; do echo "file '$f.mp4'" >> list.txt; done
ffmpeg -y -loglevel error -f concat -safe 0 -i list.txt -c copy ../base2.mp4
cd ..; ffprobe -v error -count_frames -show_entries stream=nb_read_frames -of csv=p=0 base2.mp4
T=t
ffmpeg -y -loglevel error -i base2.mp4 \
 -loop 1 -i $T/c1.png  -loop 1 -i $T/c2.png  -loop 1 -i $T/c3.png  -loop 1 -i $T/c4.png \
 -loop 1 -i $T/c5.png  -loop 1 -i $T/c6.png  -loop 1 -i $T/c7.png  -loop 1 -i $T/c8.png \
 -loop 1 -i $T/c9.png  -loop 1 -i $T/c11.png -loop 1 -i $T/c12.png -loop 1 -i $T/c13.png \
 -loop 1 -i $T/c14.png -loop 1 -i $T/c15.png \
 -filter_complex "\
[0:v][1:v]overlay=0:0:enable='between(t,0.10,1.05)'[a1];\
[a1][2:v]overlay=0:0:enable='between(t,1.40,2.30)'[a2];\
[a2][3:v]overlay=0:0:enable='between(t,2.70,4.90)'[a3];\
[a3][4:v]overlay=0:0:enable='between(t,4.95,7.05)'[a4];\
[a4][5:v]overlay=0:0:enable='between(t,7.40,9.15)'[a5];\
[a5][6:v]overlay=0:0:enable='between(t,9.20,12.30)'[a6];\
[a6][7:v]overlay=0:0:enable='between(t,12.55,14.55)'[a7];\
[a7][8:v]overlay=0:0:enable='between(t,14.78,16.10)'[a8];\
[a8][9:v]overlay=0:0:enable='between(t,16.45,19.10)'[a9];\
[a9][10:v]overlay=0:0:enable='between(t,19.50,21.25)'[a10];\
[a10][11:v]overlay=0:0:enable='between(t,21.55,23.95)'[a11];\
[a11][12:v]overlay=0:0:enable='between(t,24.25,25.95)'[a12];\
[a12][13:v]overlay=0:0:enable='between(t,26.00,28.90)'[a13];\
[a13][14:v]overlay=0:0:enable='between(t,29.25,31.80)'[vout]" \
 -map "[vout]" -frames:v 844 -an -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p capped2.mp4
D=35.1667
ffmpeg -y -loglevel error -i capped2.mp4 -i vo/voice.wav -i vo/mzr2.mp3 -filter_complex "\
[1:a]apad,atrim=0:$D,asetpts=N/SR/TB,asplit=2[vb1][vb2];\
[2:a]atrim=0:$D,asetpts=N/SR/TB,volume=0.17,afade=t=out:st=34.4:d=0.75[mus];\
[mus][vb1]sidechaincompress=threshold=0.03:ratio=12:attack=8:release=350[md];\
[vb2][md]amix=inputs=2:duration=first:normalize=0,volume=7dB,alimiter=limit=0.75,volume=-6.3dB[aout]" \
 -map 0:v -map "[aout]" -c:v copy -c:a aac -b:a 192k -ar 48000 -ac 2 -t $D dofek-rant-v2.mp4
ffmpeg -hide_banner -nostats -i dofek-rant-v2.mp4 -af ebur128=peak=true -f null - 2>&1 | grep -E "I:|Peak:" | tail -2
echo BUILD_DONE
